def count_even_xor_subsets(nums):
    n = len(nums)
    count = 0
    for mask in range(1 << n):
        xor_val = 0
        m = mask
        idx = 0
        while m:
            if m & 1:
                xor_val ^= nums[idx]
            m >>= 1
            idx += 1
        if xor_val % 2 == 0:
            count += 1
    return count
